    var SUBTITLE_COUNT  = 3;
    var events          = [{"ms": 1619136000000, "date": "2021-04-23", "label": "Paradigm on Staking Derivatives", "desc": "In their article, Hasu and Georgios Konstantopoulos argued that, because of the existance of staking derivatives, the staking participation rate could reach 80-100%."}, {"ms": 1653004800000, "date": "2022-05-20", "label": "Danny Ryan: \"The Risks of LSD\"", "desc": "Danny Ryan published an article highlighting concerns that liquid staking services, such as Lido (which held almost 33% of all staked ETH at the time), would pose a threat to Ethereum's consensus model if they grew too large."}, {"ms": 1663200000000, "date": "2022-09-15", "label": "The Merge", "desc": "Ethereum's proof-of-work era came to an end as the execution layer and proof-of-stake consensus layer were merged."}, {"ms": 1675900800000, "date": "2023-02-09", "label": "SEC vs Kraken", "desc": "The SEC settled with Kraken, having stated that its staking service constituted an unregistered securities offering. Kraken was required to shut the service down and pay $30 million. Exiting Kraken validators constituted the bulk of the ETH withdrawn in the weeks following the Shapella upgrade."}, {"ms": 1681257600000, "date": "2023-04-12", "label": "Shapella upgrade", "desc": "Ethereum's Shapella upgrade allowed stakers to withdraw their funds from the Consensus Layer back to the Execution Layer. The possibility of withdrawal significantly derisked Ethereum staking, leading to large inflows of new stake."}, {"ms": 1686700800000, "date": "2023-06-14", "label": "Eigenlayer points", "desc": "Eigenlayer announced a points system for restakers which was widely (and correctly) assumed to be a precursor to an airdrop, driving increased staking demand by stakers hoping to be rewarded with future tokens."}, {"ms": 1700524800000, "date": "2023-11-21", "label": "Blast bridge", "desc": "The Blast L2 promised \"native yield\" to its users by staking all ETH deposits, which were accepted for several months prior to its launch in February 2024. By this time Blast had amassed over 600k ETH in deposits."}, {"ms": 1708560000000, "date": "2024-02-22", "label": "Issuance debate", "desc": "Ethereum Foundation researchers Ansgar Dietrichs and Caspar Schwarz-Schilling published articles arguing that Ethereum's issuance policy would lead to a much greater than desired staking level, outlining the negative consequences of this and arguing for a swift issuance reduction."}, {"ms": 1710288000000, "date": "2024-03-13", "label": "Dencun upgrade", "desc": "The Dencun upgrade introduced blobs, promoting a move from L1 to L2 blockchains and a significant reduction in validator execution income as well as fee burn. Meanwhile, the reduction in churn limit reduced the rate at which the active stake could grow."}, {"ms": 1727740800000, "date": "2024-10-01", "label": "EIGEN unlock", "desc": "The EIGEN token unlock brought an end to airdrop farming, which had stimulated increased staking participation for an extended period. Some participants began withdrawing their stake. The staking ratio peaked a few weeks later."}, {"ms": 1748476800000, "date": "2025-05-29", "label": "SEC  Proof-of-Stake guidance", "desc": "Reversing its position under the previous administration, the SEC issued guidance that within certain parameters, staking services would not be regulated as securities. New stake immediately flooded in, and the entry queue has not fully cleared since this announcement."}, {"ms": 1752796800000, "date": "2025-07-18", "label": "AAVE rate shock", "desc": "A large AAVE withdrawal triggered an ETH lending rate spike, which in turn caused an unwind of looped staking positions."}, {"ms": 1757462400000, "date": "2025-09-10", "label": "Kiln Security Exit", "desc": "A security incident led to the Kiln staking provider withdrawing their entire stake."}, {"ms": 1766793600000, "date": "2025-12-27", "label": "BitMine Begins Staking", "desc": "Major ETH treasury BitMine started staking its Ether leading to further large consensus layer inflows and staking ratios above 30% for the first time."}];
